import requests
import time

def deny_access(url):
  while True:
    try:
      response = requests.get(url)
      if response.status_code == 200:
        print(f"Access granted to {url}")
        break
      else:
        print(f"Access denied to {url}")
        time.sleep(1)
    except requests.exceptions.RequestException as e:
      print(f"Access denied to {url}")
      time.sleep(1)
